    fun getBrandColor(merchantName: String): String? {
        val normalized = merchantName.lowercase()
        sriLankaBrandColors.entries
            .filter { (key, _) -> normalized.containsWord(key) }
            .maxByOrNull { (key, _) -> key.length }
            ?.value
            ?.let { return it }
        return legacyBrandColor(merchantName)
    }

